function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['csrf'];}
function valid_csrf():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid request');}}
function auth():bool{return !empty($_SESSION['ferrn_admin']);}
function go(string $tab='dashboard'):never{header('Location: /admin/?tab='.$tab);exit;}
$error='';
if(isset($_GET['logout'])){session_destroy();header('Location:/admin/');exit;}
if(!auth()&&$_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='login'){$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if($email===strtolower(ADMIN_EMAIL)&&password_verify($pw,ADMIN_HASH)){session_regenerate_id(true);$_SESSION['ferrn_admin']=1;csrf();go();}$error='Incorrect email or password.';}
if(auth()&&$_SERVER['REQUEST_METHOD']==='POST'){valid_csrf();$action=(string)($_POST['action']??'');
 if($action==='lead_status'){$leads=ferrn_leads();$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'new');if(!in_array($status,['new','contacted','qualified','proposal','won','lost'],true))$status='new';foreach($leads as &$l)if(($l['id']??'')===$id)$l['status']=$status;unset($l);ferrn_save_json('leads.json',$leads);go('leads');}
 if($action==='delete_lead'){$id=(string)($_POST['id']??'');ferrn_save_json('leads.json',array_values(array_filter(ferrn_leads(),fn($l)=>($l['id']??'')!==$id)));go('leads');}
 if($action==='save_post'){$posts=ferrn_posts();$id=(string)($_POST['id']??'');$title=trim((string)($_POST['title']??''));$content=ferrn_sanitize_html((string)($_POST['content']??''));if($title===''||trim(strip_tags($content))===''){$error='Post title and body are required.';}else{$slug=ferrn_slugify((string)($_POST['slug']?:$title));$now=date(DATE_ATOM);$status=($_POST['status']??'draft')==='published'?'published':'draft';$item=['title'=>$title,'slug'=>$slug,'category'=>trim((string)($_POST['category']??'Insight')),'excerpt'=>trim((string)($_POST['excerpt']??''))?:ferrn_excerpt($content),'content'=>$content,'status'=>$status,'updated_at'=>$now];$found=false;foreach($posts as &$p)if(($p['id']??'')===$id&&$id!==''){$found=true;$created=$p['created_at']??$now;$published=$p['published_at']??null;$p=array_merge($p,$item,['created_at'=>$created,'published_at'=>$status==='published'?($published?:$now):$published]);}unset($p);if(!$found)$posts[]=array_merge(['id'=>bin2hex(random_bytes(6)),'created_at'=>$now,'published_at'=>$status==='published'?$now:null],$item);ferrn_save_json('posts.json',$posts);go('posts');}}
 if($action==='delete_post'){$id=(string)($_POST['id']??'');ferrn_save_json('posts.json',array_values(array_filter(ferrn_posts(),fn($p)=>($p['id']??'')!==$id)));go('posts');}
 if($action==='save_project'){$projects=ferrn_projects();$old=(string)($_POST['old_slug']??'');$title=trim((string)($_POST['title']??''));$live=trim((string)($_POST['live']??''));if($title===''||!filter_var($live,FILTER_VALIDATE_URL)){$error='Project title and a valid live URL are required.';}else{$slug=ferrn_slugify((string)($_POST['slug']?:$title));$category=in_array(($_POST['category']??''),['website','webapp','ai'],true)?(string)$_POST['category']:'website';$project=['title'=>$title,'type'=>trim((string)($_POST['type']??'Digital Project')),'category'=>$category,'industry'=>trim((string)($_POST['industry']??'Digital Product')),'year'=>trim((string)($_POST['year']??date('Y'))),'live'=>$live,'client'=>trim((string)($_POST['client']??$title)),'featured'=>!empty($_POST['featured']),'meta'=>trim((string)($_POST['meta']??'')),'summary'=>trim((string)($_POST['summary']??'')),'context'=>trim((string)($_POST['context']??'')),'challenge'=>trim((string)($_POST['challenge']??'')),'solution'=>trim((string)($_POST['solution']??'')),'impact'=>trim((string)($_POST['impact']??'')),'points'=>ferrn_project_points($category)];if($old!==''&&$old!==$slug)unset($projects[$old]);$projects[$slug]=$project;ferrn_save_projects($projects);go('projects');}}
 if($action==='delete_project'){$slug=(string)($_POST['slug']??'');$projects=ferrn_projects();unset($projects[$slug]);ferrn_save_projects($projects);go('projects');}
}
