:#ffa088}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:span 2}.field label{font-size:10px;color:#888}.field input,.field textarea,.field select,select{background:#080808;border:1px solid #2b2b2b;color:#fff;border-radius:10px;padding:12px}.field textarea{min-height:110px;resize:vertical}.field.body textarea{min-height:300px}.check{display:flex;gap:8px;align-items:center;font-size:12px;color:#aaa}.check input{width:auto}.panel-head{display:flex;justify-content:space-between;gap:15px;align-items:center}.error{padding:10px;background:#35130c;color:#ffa088;border-radius:10px;margin-bottom:12px}@media(max-width:900px){.app{grid-template-columns:1fr}.side{height:auto;position:static;display:flex;align-items:center;gap:4px;overflow:auto;border-right:0;border-bottom:1px solid #252525}.side img{margin:0 8px 0 0;width:28px}.side a{white-space:nowrap}.logout{position:static;margin-left:auto}.cards{grid-template-columns:1fr 1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}}</style></head><body><div class="app"><aside class="side"><img src="/assets/ferrn-mark.svg" alt="Ferrn"><a class="<?=$tab==='dashboard'?'active':''?>" href="?tab=dashboard">Dashboard</a><a class="<?=$tab==='leads'?'active':''?>" href="?tab=leads">Leads</a><a class="<?=$tab==='projects'?'active':''?>" href="?tab=projects">Projects</a><a class="<?=$tab==='posts'?'active':''?>" href="?tab=posts">Posts</a><a class="logout" href="?logout=1">Sign out</a></aside><main class="main"><div class="top"><div><div class="muted">FERRN DIGITAL AGENCY</div><h1><?=ucfirst($tab)?></h1></div><a class="btn secondary" href="/" target="_blank">View website</a></div><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?>
